using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CosmicOrbStarAbility", menuName = "Data/Battle/Effects/Orion/CosmicOrb Star Ability")]
public class CosmicOrbStarAbility : ActivateStarAbility
{
	private const string CosmicOrbAllTargetsDescriptionID = "CosmicOrbAllTargetsDescription";

	[Header("Shooting Star Modifier Effects")]
	[SerializeField]
	private Effect cosmicDustEffect;

	[SerializeField]
	private Effect cosmicExpansionEffect;

	[SerializeField]
	private OmenLogic allTargetsOmenLogic;

	[Header("Omens")]
	[SerializeField]
	private PlatinumStarOmenData platinumStarOmenData;

	[SerializeField]
	private ShootingStarOmenData shootingStarOmenData;

	[Header("Description")]
	[SerializeField]
	private BattleAction randomEnemyPurifyAction;

	[SerializeField]
	private BattleAction areaPurifyAction;

	[SerializeField]
	private BattleAction randomPurifyAction;

	private UnitEffects unitEffects => ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<UnitEffects>();

	protected override int GetModifiedActionValue()
	{
		return (battleAction as PurifyAction).GetModifiedPurifyAmount(actionValue + GetCosmicDustEffectAmount(activateFeedback: false), chanting: false, effectBasedAreaPurify: false, GetCastOrbSource());
	}

	public override string GetLocalizedDescription()
	{
		return GetLocalizedDescriptionWithCastOrb(GetLocalizedDescriptionWithModifications());
	}

	private string GetLocalizedDescriptionWithModifications()
	{
		BattleAction battleAction = randomEnemyPurifyAction;
		if (GameScenesUtils.IsBattleScene())
		{
			if (unitEffects.IsEffectActive(cosmicExpansionEffect))
			{
				battleAction = areaPurifyAction;
			}
			else if (ReferenceSingleton<OrionOmensHandler>.Instance.IsShootingStarOmenActive(activateFeedback: true))
			{
				battleAction = randomPurifyAction;
			}
			int cosmicDustEffectAmount = GetCosmicDustEffectAmount(activateFeedback: true);
			return battleAction.GetActionDescription(actionValue, cosmicDustEffectAmount);
		}
		return battleAction.GetActionDescription(actionValue);
	}

	public override void OnActivateStarAbility()
	{
		ReferenceSingleton<OrionOmensHandler>.Instance.ConstellationBeadsOmenAction?.Invoke();
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CosmicOrbCastedAmount++;
		if (unitEffects.IsEffectActiveAndDecreaseEffect(cosmicExpansionEffect, 1))
		{
			PlaySFX();
			CheckDisableEnqueueNormalPurifyCorruptCoroutineAction();
			BattleAction battleAction = ((ReferenceSingleton<OrionOmensHandler>.Instance.PlatinumStarOmenAction != null) ? platinumStarOmenData.OrionAreaPlatinumStarAction : base.battleAction);
			allTargetsOmenLogic.ActivateOmen(battleAction, GetModifiedActionValue(), null, GetCastOrbSource());
		}
		else
		{
			base.OnActivateStarAbility();
		}
	}

	protected override BattleAction GetBattleAction()
	{
		if (ReferenceSingleton<OrionOmensHandler>.Instance.PlatinumStarOmenAction != null)
		{
			return platinumStarOmenData.OrionPlatinumStarAction;
		}
		return battleAction;
	}

	protected override OmenLogic GetOmenLogic()
	{
		if (ReferenceSingleton<OrionOmensHandler>.Instance.IsShootingStarOmenActive(activateFeedback: false))
		{
			return shootingStarOmenData.RandomTargetOmenLogic;
		}
		return omenLogic;
	}

	private int GetCosmicDustEffectAmount(bool activateFeedback)
	{
		return unitEffects.IsEffectActiveGetAmount(cosmicDustEffect, activateFeedback);
	}
}
